#include <queue>
#include <vector>
#include <iostream>

int main() {
    std::vector<int> data = {1, 8, 3, 5, 2};
    // O(N) construction time, using make_heap internally
    std::priority_queue<int> pq(data.begin(), data.end());

    // O(log N) insertion
    pq.push(10);

    // O(log N) extraction
    while (!pq.empty()) {
        std::cout << pq.top() << " "; // Access highest priority
        pq.pop(); 
    }
    // Output: 10 8 5 3 2 1
}
